ruleToc.chapterList:
@js:
var doc = org.jsoup.Jsoup.parse(result);

//写法1
var list = [];
doc.select(".book_list a").toArray()
  .forEach((a,i) => list[3-i%4+4*(i-i%4)/4] = a);
list;

//写法2
var list = [];
doc.select(".book_list a").toArray()
  .forEach((a,i) => list[3-i%4+4*(i-i%4)/4] = {
     text: a.text().replaceAll("^\\d+\\.",""),
     href: a.attr("href")
  });
list;
